const e = $json;
const workingDays = 22; // Số ngày công chuẩn
const dailyRate = e.base_salary / workingDays;
const overtimeRate = dailyRate / 8 * 1.5;
const overtimeHours = Math.max(0, e.total_hours - (workingDays * 8));
const grossSalary = Math.round(
  (e.worked_days * dailyRate) + (overtimeHours * overtimeRate)
);
const taxRate = grossSalary > 20000000 ? 0.15 : 0.10;
const socialInsurance = Math.round(e.base_salary * 0.105);
const netSalary = Math.round(grossSalary * (1 - taxRate) - socialInsurance);
return [{json: {
  ...e,
  gross_salary: grossSalary,
  net_salary: netSalary,
  tax_amount: Math.round(grossSalary * taxRate),
  social_insurance: socialInsurance,
  overtime_hours: overtimeHours,
  period: new Date().toISOString().substring(0, 7)
}}];
